// Join-site workbench page: runs only inside a frame of this same site (the guest app's own workbench frame). Anywhere else (opened on its
// own, or framed by another site) the page is blanked before any library loads. (Generated by scripts/build-join-site-app.js.)
(function () {
  var ok = false;
  try {
    ok = window.parent !== window && window.parent.location.origin === window.location.origin;
  } catch (_) {
    ok = false; /* a cross-origin parent throws */
  }
  if (ok) return;
  document.documentElement.hidden = true;
  throw new Error("not in this site's frame");
})();
